import{_ as t}from"./chunks/mixed.BGioRLlz.js";import{_ as a,o as r,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"About","description":"","frontmatter":{"title":"About"},"headers":[],"relativePath":"en/projects/uix/index.md","filePath":"en/projects/uix/index.md","lastUpdated":1792861636000}'),s={name:"en/projects/uix/index.md"};function i(l,e,c,h,u,d){return r(),o("div",null,[...e[0]||(e[0]=[n('<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.0.0-beta.2</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/26e54e6d4973231a393933e6479ed1b03cc86cd3" target="_blank" rel="noreferrer">26e54e6</a>, reviewed 22 October 2026. This source mirror may describe preview behavior beyond stable 8.4.0. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="ui-extension-for-home-assistant" tabindex="-1">UI eXtension for Home Assistant <a class="header-anchor" href="#ui-extension-for-home-assistant" aria-label="Permalink to &quot;UI eXtension for Home Assistant&quot;">​</a></h1><p><img src="'+t+'" alt="light-logo-icon"></p><h2 id="what-is-ui-extension" tabindex="-1">What is UI eXtension? <a class="header-anchor" href="#what-is-ui-extension" aria-label="Permalink to &quot;What is UI eXtension?&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Card-mod users</p><p>If you are migrating from Card-mod check out the <a href="/en/projects/uix/faq">FAQ</a> where most of your questions will be answered. If you need to ask anything further, use the <a href="https://github.com/Lint-Free-Technology/uix/discussions" target="_blank" rel="noreferrer">GitHub discussions</a>.</p></div><p>With an ever growing number of features that go beyond cards and dashboards, UI eXtension (UIX) was created to keep pushing the boundaries of custom CSS across your Home Assistant UI. UIX comes from the heritage of <a href="https://github.com/thomasloven/lovelace-card-mod" target="_blank" rel="noreferrer">card-mod</a> by <a href="https://github.com/thomasloven" target="_blank" rel="noreferrer">@thomasloven</a></p><p>UI eXtension consists of <a href="./using/">UIX Styling</a>, <a href="./forge/">UIX Forge</a> and <a href="./broker/">UIX Broker</a>. <a href="./using/">UIX Styling</a> allows for applying CSS styles to (nearly) any Home Assistant Frontend element. <a href="./forge/">UIX Forge</a> provides a way to forge Home Assistant elements (cards, badges, rows etc.) allowing for templates for all of the element&#39;s configuration, as well as additional advanced augmentation of the element through <a href="./forge/sparks/">UIX Forge Sparks</a>. UIX Broker turns browser events, keyboard shortcuts, and Home Assistant event-bus events into declarative interactions. An interaction selects a browser element, checks optional rules, then runs directives in their configured order.</p><h2 id="🚀-quick-start" tabindex="-1">🚀 Quick Start <a class="header-anchor" href="#🚀-quick-start" aria-label="Permalink to &quot;🚀 Quick Start&quot;">​</a></h2><p>Go to <a href="./quick-start">Quick Start</a> for installation instructions and a short guide on making your first UIX Styling and UIX Forge.</p><h2 id="➡️-next-up" tabindex="-1">➡️ Next up <a class="header-anchor" href="#➡️-next-up" aria-label="Permalink to &quot;➡️ Next up&quot;">​</a></h2><ul><li><a href="./using/">Using UIX Styling</a></li><li><a href="./forge/">Using UIX Forge</a></li><li><a href="/en/projects/uix/faq">FAQ</a></li></ul>',11)])])}const p=a(s,[["render",i]]);export{g as __pageData,p as default};
